import os,glob,re
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load(); print(sorted(G))
inp,out=G['Demo pair 1 input'],G['Demo pair 1 output']
from collections import Counter
bg=Counter(v for r in inp for v in r).most_common(1)[0][0]
print('bg',bg)
def comps(g,bg):
    h,w=len(g),len(g[0]); seen=set(); res=[]
    for i in range(h):
        for j in range(w):
            if g[i][j]==bg or (i,j) in seen: continue
            c=g[i][j]; st=[(i,j)]; seen.add((i,j)); cells=[]
            while st:
                y,x=st.pop(); cells.append((y,x))
                for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                    ny,nx=y+dy,x+dx
                    if 0<=ny<h and 0<=nx<w and g[ny][nx]==c and (ny,nx) not in seen:
                        seen.add((ny,nx)); st.append((ny,nx))
            res.append((c,cells))
    return res
for c,cells in comps(inp,bg):
    ys=[y for y,_ in cells]; xs=[x for _,x in cells]
    bb=(min(ys),min(xs),max(ys),max(xs))
    print(c,len(cells),bb)
print('---output comps')
for c,cells in comps(out,bg): print(c,len(cells),(min(y for y,_ in cells),min(x for _,x in cells),max(y for y,_ in cells),max(x for _,x in cells)))
